package main

import (
	"crypto/md5"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"sync/atomic"
)

var shards = []map[int]interface{}{{}, {}}
var nextID int64

func getShard(id int) int {
	hash := md5.Sum([]byte(fmt.Sprintf("%d", id)))
	return int(hash[0]) % 2
}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		id := int(atomic.AddInt64(&nextID, 1))
		shardIdx := getShard(id)
		var body struct { Name string `json:"name"`; Email string `json:"email"` }
		json.NewDecoder(r.Body).Decode(&body)
		shards[shardIdx][id] = map[string]interface{}{"id": id, "name": body.Name, "email": body.Email}
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(map[string]interface{}{"id": id, "name": body.Name, "email": body.Email, "shard": shardIdx})
	})

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"status": "ok", "shards": 2})
	})

	http.ListenAndServe(":"+port, nil)
}

