import (
	"crypto/md5"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
)

var shards = []map[int]interface{}{{}, {}}
var nextID int64

func getShard(id int) int {
	hash := md5.Sum([]byte(fmt.Sprintf("%d", id)))
	return int(hash[0]) % 2
}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/users/"), "/")
		if len(parts) == 0 || parts[0] == "" { http.NotFound(w, r); return }
		id, _ := strconv.Atoi(parts[0])
		s := getShard(id)
		user, ok := shards[s][id]
		if !ok { w.WriteHeader(404); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
		json.NewEncoder(w).Encode(user)
	})

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		id := int(atomic.AddInt64(&nextID, 1))
		s := getShard(id)
		var body struct { Name string `json:"name"`; Email string `json:"email"` }
		json.NewDecoder(r.Body).Decode(&body)
		shards[s][id] = map[string]interface{}{"id": id, "name": body.Name, "email": body.Email}
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(map[string]interface{}{"id": id, "name": body.Name, "email": body.Email, "shard": s})
	})

	http.ListenAndServe(":"+port, nil)
}

